        (void)geostar_write(session, 0x84, buf, 1);
        // Poll Protocols assignment
        (void)geostar_write(session, 0x86, buf, 1);
        // Poll PPS params
        (void)geostar_write(session, 0x8c, buf, 1);
        // Poll NMEA packets selected
